const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,d=2)=>finite(x)?x.toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:Math.abs(x)<10?d:0}):'—';
const engine=new EngineClient();
const models={
 beta:{name:'Updating a belief',meta:'Beta–Binomial · 1 dimension',glyph:'β',title:'From prior belief to posterior',assumption:'A Beta prior meets binomial observations. Inference uses a logit coordinate with its change-of-variables Jacobian.',insight:'The posterior is a distribution, not a single answer. Compare the computed approximation with the exact update.',config:{alpha:2,beta:2,successes:7,trials:10}},
 regression:{name:'Predicting with uncertainty',meta:'Linear regression · 2 dimensions',glyph:'↗',title:'A prediction is more than a line',assumption:'An intercept and slope have independent Gaussian priors. Observation noise is known. All imported data stays in this browser.',insight:'The mean-response credible band describes uncertainty in the line. The wider predictive band also includes observation noise.',config:{noise:.7,prior_scale:3}},
 gaussian:{name:'The cost of independence',meta:'Correlated Gaussian · 2 dimensions',glyph:'∿',title:'Correlation defeats factorization',assumption:'A normalized two-dimensional Gaussian. The true marginal scales are known; a factorized approximation cannot represent correlation.',insight:'At correlation 0.95, the exact reverse-KL mean-field variance is 0.0975, while the true marginal variance is 1. Optimization can succeed while uncertainty is understated.',config:{correlation:.95,scale:1}},
 funnel:{name:'Inside the funnel',meta:'Hierarchical geometry · 6 dimensions',glyph:'⋈',title:'One model. Two geometries.',assumption:'A no-data hierarchy: y ∼ Normal(0, 3); five children have standard deviation exp(y / 2). Reference draws use its generative construction.',insight:'Explore the same hierarchy in centered and noncentered coordinates. The visible axes always show y and the first model-space child; short runs may miss the narrow region.',config:{noncentered:false}},
 mixture:{name:'What the chains might miss',meta:'Separated mixture · 2 dimensions',glyph:'⌁',title:'Good agreement can miss a mode',assumption:'A normalized mixture: 70% around (−4, 0), 30% around (4, 0), with coordinate variances (0.25, 1).',insight:'Chains can agree because they are all trapped in one mode. Equal draw counts from separated modes do not recover the known 70:30 weights.',config:{}}
};
